import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
		int t = sc.nextInt();
		while(t-->0){
		    int n = sc.nextInt();
		    int m = 3*n;
		    long a[] = new long[m];
		    for(int i=0;i<m;i++)
		    {
		        a[i] = sc.nextLong();
		    }
		    Arrays.sort(a);
		    long s[] = new long[m+1];
		    for(int i =0;i<m;i++)
		    {
		        s[i+1] = s[i]+a[i];
		    }
		    long ans=0;
		    for(int x=0;x<=n;x++)
		    {
		        int lo = 0;
		        int hi=n-x;
		        while(lo<hi)
		        
		        {
		            int b = (lo+hi)/2;
		            int p =m-x-2*b;
		            int q = 2*x+b;
		            long gain =a[p-2]+a[p-1]-3*a[q];
		            if(gain>=0)
		            {
		                lo=b+1;
		            }
		            else{
		                hi = b;
		            }
		        }
		        for(int b=Math.max(0,lo-1);b<=Math.min(n-x,lo);b++)
		        {
		            int p = m-x-2*b;
		            int q = 2*x+b;
		            long val = 6*(s[m]-s[m-x])+4*(s[m-x]-s[p])+3*(s[p]-s[q]);
		            ans = Math.max(ans,val);
		        }
		    }
		    System.out.println(ans);
		}

	}
}
